export default function () {
  this.route("workflows-form", {
    path: "/workflows/form/:uuid",
    bundleName: "workflows-form",
  });
  this.route("workflows-form-test", {
    path: "/workflows/form-test/:token",
    bundleName: "workflows-form",
  });
}
import { withPluginApi } from "discourse/lib/plugin-api";

const PLUGIN_ID = "discourse-workflows";

export default {
  name: "discourse-workflows-admin-plugin-configuration-nav",

  initialize(container) {
    const currentUser = container.lookup("service:current-user");
    if (!currentUser?.admin) {
      return;
    }

    withPluginApi((api) => {
      api.addAdminPluginConfigurationNav(PLUGIN_ID, [
        {
          label: "discourse_workflows.title",
          route: "adminPlugins.show.discourse-workflows.index",
          currentWhen:
            "adminPlugins.show.discourse-workflows.index adminPlugins.show.discourse-workflows.new adminPlugins.show.discourse-workflows.show.index adminPlugins.show.discourse-workflows.show.node adminPlugins.show.discourse-workflows.show.executions.index adminPlugins.show.discourse-workflows.show.executions.show adminPlugins.show.discourse-workflows.show.settings",
        },
        {
          label: "discourse_workflows.variables.title",
          route: "adminPlugins.show.discourse-workflows-variables",
        },
        {
          label: "discourse_workflows.credentials.title",
          route: "adminPlugins.show.discourse-workflows-credentials",
        },
        {
          label: "discourse_workflows.data_tables.title",
          route: "adminPlugins.show.discourse-workflows-data-tables",
        },
        {
          label: "discourse_workflows.executions.title",
          route: "adminPlugins.show.discourse-workflows-executions",
        },
        {
          label: "discourse_workflows.templates.title",
          route: "adminPlugins.show.discourse-workflows-templates",
        },
      ]);
      api.setAdminPluginIcon(PLUGIN_ID, "code-branch");
    });
  },
};
const CODE_SELECTOR = "pre code";
const WORKFLOW_PREVIEW_KIND = "discourse_admin_assistant_workflow_preview_v1";
const MAX_PREVIEW_NODES = 24;
const MAX_PREVIEW_CONNECTIONS = 48;
const MAX_PREVIEW_OPERATIONS = 200;

function normalizeOperation(operation) {
  if (typeof operation !== "string") {
    return operation;
  }

  try {
    return JSON.parse(operation);
  } catch {
    return null;
  }
}

function nodeReference(operation, primary, fallback) {
  return operation[primary] ?? operation[fallback];
}

function stronglyConnectedComponents(nodes, connections) {
  const nodeIds = new Set(nodes.map((node) => node.id));
  const outgoing = new Map(nodes.map((node) => [node.id, []]));

  for (const connection of connections) {
    if (nodeIds.has(connection.from) && nodeIds.has(connection.to)) {
      outgoing.get(connection.from).push(connection.to);
    }
  }

  let nextIndex = 0;
  const components = [];
  const indexes = new Map();
  const lowLinks = new Map();
  const stack = [];
  const stacked = new Set();

  const visit = (nodeId) => {
    indexes.set(nodeId, nextIndex);
    lowLinks.set(nodeId, nextIndex);
    nextIndex++;
    stack.push(nodeId);
    stacked.add(nodeId);

    for (const targetId of outgoing.get(nodeId)) {
      if (!indexes.has(targetId)) {
        visit(targetId);
        lowLinks.set(
          nodeId,
          Math.min(lowLinks.get(nodeId), lowLinks.get(targetId))
        );
      } else if (stacked.has(targetId)) {
        lowLinks.set(
          nodeId,
          Math.min(lowLinks.get(nodeId), indexes.get(targetId))
        );
      }
    }

    if (lowLinks.get(nodeId) !== indexes.get(nodeId)) {
      return;
    }

    const component = [];
    let currentId;
    do {
      currentId = stack.pop();
      stacked.delete(currentId);
      component.push(currentId);
    } while (currentId !== nodeId);
    components.push(component);
  };

  for (const node of nodes) {
    if (!indexes.has(node.id)) {
      visit(node.id);
    }
  }

  return components;
}

function assignColumns(nodes, connections) {
  const components = stronglyConnectedComponents(nodes, connections);
  const componentByNode = new Map();
  components.forEach((component, componentIndex) => {
    component.forEach((nodeId) => componentByNode.set(nodeId, componentIndex));
  });

  const incoming = new Map(components.map((_, index) => [index, new Set()]));
  const outgoing = new Map(components.map((_, index) => [index, new Set()]));

  for (const connection of connections) {
    const source = componentByNode.get(connection.from);
    const target = componentByNode.get(connection.to);
    if (source === undefined || target === undefined || source === target) {
      continue;
    }
    outgoing.get(source).add(target);
    incoming.get(target).add(source);
  }

  const componentColumns = new Map();
  const queue = components
    .map((_, index) => index)
    .filter((index) => incoming.get(index).size === 0);

  while (queue.length) {
    const componentIndex = queue.shift();
    const column = componentColumns.get(componentIndex) ?? 0;

    for (const target of outgoing.get(componentIndex)) {
      componentColumns.set(
        target,
        Math.max(componentColumns.get(target) ?? 0, column + 1)
      );
      incoming.get(target).delete(componentIndex);
      if (incoming.get(target).size === 0) {
        queue.push(target);
      }
    }
  }

  return {
    columns: new Map(
      nodes.map((node) => [
        node.id,
        componentColumns.get(componentByNode.get(node.id)) ?? 0,
      ])
    ),
    hasCycle:
      components.some((component) => component.length > 1) ||
      connections.some((connection) => connection.from === connection.to),
  };
}

function graphFromOperations(operations) {
  const nodes = [];
  const nodesByReference = new Map();
  let nextNodeId = 0;
  let connections = [];

  const resolveNode = (reference) => nodesByReference.get(String(reference));

  for (const rawOperation of operations) {
    const operation = normalizeOperation(rawOperation);
    if (!operation || typeof operation !== "object") {
      return null;
    }

    switch (operation.op) {
      case "create_ai_agent":
      case "update_node_parameters":
        break;
      case "add_node": {
        const node = operation.node;
        if (!node || typeof node !== "object" || !node.name || !node.type) {
          return null;
        }

        const id = `node-${nextNodeId++}`;
        const previewNode = {
          id,
          name: String(node.name),
          type: String(node.type),
        };
        nodes.push(previewNode);
        nodesByReference.set(String(operation.client_id ?? id), previewNode);
        if (node.id) {
          nodesByReference.set(String(node.id), previewNode);
        }
        break;
      }
      case "rename_node": {
        const node = resolveNode(
          nodeReference(operation, "node_id", "client_id")
        );
        if (!node || !operation.name) {
          return null;
        }
        node.name = String(operation.name);
        break;
      }
      case "remove_node": {
        const node = resolveNode(
          nodeReference(operation, "node_id", "client_id")
        );
        if (!node) {
          return null;
        }
        nodes.splice(nodes.indexOf(node), 1);
        for (const [reference, referencedNode] of nodesByReference) {
          if (referencedNode === node) {
            nodesByReference.delete(reference);
          }
        }
        connections = connections.filter(
          (connection) =>
            connection.from !== node.id && connection.to !== node.id
        );
        break;
      }
      case "add_connection": {
        const source = resolveNode(
          nodeReference(operation, "from", "from_node_id")
        );
        const target = resolveNode(
          nodeReference(operation, "to", "to_node_id")
        );
        if (!source || !target) {
          return null;
        }
        connections.push({
          from: source.id,
          to: target.id,
          connectionType: String(operation.connection_type ?? "main"),
          outputIndex: Number(operation.output_index ?? 0),
          inputIndex: Number(operation.input_index ?? 0),
        });
        break;
      }
      case "remove_connection": {
        const source = resolveNode(
          nodeReference(operation, "from", "from_node_id")
        );
        const target = resolveNode(
          nodeReference(operation, "to", "to_node_id")
        );
        if (!source || !target) {
          return null;
        }
        connections = connections.filter((connection) => {
          if (connection.from !== source.id || connection.to !== target.id) {
            return true;
          }
          if (
            operation.output_index !== undefined &&
            connection.outputIndex !== Number(operation.output_index)
          ) {
            return true;
          }
          return (
            operation.input_index !== undefined &&
            connection.inputIndex !== Number(operation.input_index)
          );
        });
        break;
      }
      default:
        return null;
    }
  }

  if (!nodes.length) {
    return null;
  }

  return { nodes, connections };
}

export function extractWorkflowPreview(cooked) {
  if (!cooked || typeof DOMParser === "undefined") {
    return null;
  }

  const document = new DOMParser().parseFromString(cooked, "text/html");
  const code = document.querySelector(CODE_SELECTOR);
  if (!code) {
    return null;
  }

  try {
    const payload = JSON.parse(code.textContent);
    if (payload?.kind !== WORKFLOW_PREVIEW_KIND) {
      return null;
    }
    const configuration = payload.configuration;
    if (
      !configuration ||
      typeof configuration.name !== "string" ||
      !Array.isArray(configuration.operations)
    ) {
      return null;
    }
    const preview = {
      name: configuration.name,
      configuration,
      shortened: payload.shortened === true,
    };
    if (configuration.operations.length > MAX_PREVIEW_OPERATIONS) {
      return { ...preview, unavailable: true };
    }

    const graph = graphFromOperations(configuration.operations);
    if (!graph) {
      return { ...preview, unavailable: true };
    }
    if (
      graph.nodes.length > MAX_PREVIEW_NODES ||
      graph.connections.length > MAX_PREVIEW_CONNECTIONS
    ) {
      return { ...preview, nodeCount: graph.nodes.length, unavailable: true };
    }

    return { ...preview, ...graph };
  } catch {
    return null;
  }
}

export function layoutWorkflowPreview(preview) {
  const nodeWidth = 176;
  const nodeHeight = 96;
  const horizontalGap = 32;
  const verticalGap = 28;
  const padding = 20;
  const { columns, hasCycle } = assignColumns(
    preview.nodes,
    preview.connections
  );
  const rowsByColumn = new Map();

  for (const node of preview.nodes) {
    const column = columns.get(node.id);
    const columnNodes = rowsByColumn.get(column) ?? [];
    columnNodes.push(node);
    rowsByColumn.set(column, columnNodes);
  }

  const positionedNodes = preview.nodes.map((node) => {
    const column = columns.get(node.id);
    const row = rowsByColumn.get(column).indexOf(node);
    return {
      ...node,
      x: padding + column * (nodeWidth + horizontalGap),
      y: padding + row * (nodeHeight + verticalGap),
    };
  });
  const positionedById = new Map(
    positionedNodes.map((node) => [node.id, node])
  );
  const maxColumn = Math.max(...columns.values());
  const maxRows = Math.max(
    ...[...rowsByColumn.values()].map((nodes) => nodes.length)
  );
  const width =
    padding * 2 + (maxColumn + 1) * nodeWidth + maxColumn * horizontalGap;
  const height =
    padding * 2 + maxRows * nodeHeight + (maxRows - 1) * verticalGap;

  const connections = preview.connections.map((connection, index) => {
    const sourceOutputIndexes = new Set(
      preview.connections
        .filter((candidate) => candidate.from === connection.from)
        .map((candidate) => candidate.outputIndex)
    );
    const branchNumber =
      sourceOutputIndexes.size > 1 ? connection.outputIndex + 1 : null;
    const source = positionedById.get(connection.from);
    const target = positionedById.get(connection.to);
    const startX = source.x + nodeWidth;
    const startY = source.y + nodeHeight / 2;
    const endX = target.x;
    const endY = target.y + nodeHeight / 2;
    let path;
    let labelX = (startX + endX) / 2;
    let labelY = (startY + endY) / 2 - 8;

    if (endX > startX) {
      const controlOffset = Math.max(28, (endX - startX) / 2);
      path = `M ${startX} ${startY} C ${startX + controlOffset} ${startY}, ${endX - controlOffset} ${endY}, ${endX} ${endY}`;
    } else {
      const loopOffset = 22 + (index % 4) * 8;
      const bottom = Math.max(startY, endY) + nodeHeight / 2 + loopOffset;
      labelX = (startX + endX) / 2;
      labelY = bottom - 6;
      path = `M ${startX} ${startY} C ${startX + loopOffset} ${startY}, ${startX + loopOffset} ${bottom}, ${startX} ${bottom} L ${endX - loopOffset} ${bottom} C ${endX - loopOffset * 2} ${bottom}, ${endX - loopOffset * 2} ${endY}, ${endX} ${endY}`;
    }

    return { ...connection, branchNumber, labelX, labelY, path };
  });

  return {
    connections,
    hasCycle,
    height,
    nodes: positionedNodes,
    nodeHeight,
    nodeWidth,
    width,
  };
}
import Component from "@glimmer/component";
import { cached } from "@glimmer/tracking";
import { trustHTML } from "@ember/template";
import { bind } from "discourse/lib/decorators";
import dIcon from "discourse/ui-kit/helpers/d-icon";
import { i18n } from "discourse-i18n";
import {
  extractWorkflowPreview,
  layoutWorkflowPreview,
} from "../../lib/admin-assistant/workflow-preview.js";

function nodeIcon(type) {
  if (type.startsWith("trigger:")) {
    return "bolt";
  }
  if (type.includes("condition") || type.includes("branch")) {
    return "code-branch";
  }
  return "gear";
}

function connectionLabel(connection) {
  if (connection.connectionType && connection.connectionType !== "main") {
    return connection.connectionType;
  }
  if (connection.branchNumber) {
    return i18n("discourse_workflows.admin_assistant.preview.branch", {
      number: connection.branchNumber,
    });
  }
  return null;
}

export default class AdminAssistantWorkflowPreview extends Component {
  @cached
  get preview() {
    const hasConfirmation = this.args.message?.blocks?.some(
      (block) => block.type === "confirmation"
    );
    if (!hasConfirmation) {
      return null;
    }

    return extractWorkflowPreview(this.args.message?.cooked);
  }

  @cached
  get layout() {
    return this.preview?.nodes ? layoutWorkflowPreview(this.preview) : null;
  }

  get hasFailedScripts() {
    const validations = this.preview?.configuration?.script_validations;
    return (
      Array.isArray(validations) &&
      validations.some((validation) => validation?.valid === false)
    );
  }

  get exactConfiguration() {
    return JSON.stringify(this.preview.configuration, null, 2);
  }

  get markerId() {
    return `assistant-workflow-preview-arrow-${this.args.message?.id ?? "draft"}`;
  }

  get markerUrl() {
    return `url(#${this.markerId})`;
  }

  get viewportStyle() {
    return trustHTML(
      `width: ${this.layout.width}px; height: ${this.layout.height}px;`
    );
  }

  @bind
  nodeConnections(node) {
    return this.layout.connections
      .filter((connection) => connection.from === node.id)
      .map((connection) => {
        const target = this.preview.nodes.find(
          (candidate) => candidate.id === connection.to
        );
        if (!target) {
          return null;
        }

        return connectionLabel(connection)
          ? `${connectionLabel(connection)}: ${target.name}`
          : target.name;
      })
      .filter(Boolean)
      .join(", ");
  }

  @bind
  nodeStyle(node) {
    return trustHTML(
      `left: ${node.x}px; top: ${node.y}px; width: ${this.layout.nodeWidth}px; height: ${this.layout.nodeHeight}px;`
    );
  }

  <template>
    {{#if this.preview}}
      <section
        aria-label={{i18n "discourse_workflows.admin_assistant.preview.label"}}
        class="assistant-workflow-preview"
      >
        <header class="assistant-workflow-preview__header">
          <span class="assistant-workflow-preview__heading">
            {{dIcon "code-branch"}}
            <span>{{this.preview.name}}</span>
          </span>
          <span class="assistant-workflow-preview__badge">
            {{i18n "discourse_workflows.admin_assistant.preview.read_only"}}
          </span>
        </header>

        {{#if this.hasFailedScripts}}
          <p class="assistant-workflow-preview__warning" role="status">
            {{i18n
              "discourse_workflows.admin_assistant.preview.script_validation_warning"
            }}
          </p>
        {{/if}}

        {{#if this.preview.shortened}}
          <p class="assistant-workflow-preview__notice">
            {{i18n "discourse_workflows.admin_assistant.preview.shortened"}}
          </p>
        {{/if}}

        {{#if this.layout}}
          <div class="assistant-workflow-preview__scroller" tabindex="0">
            <div
              class="assistant-workflow-preview__viewport"
              style={{this.viewportStyle}}
            >
              <svg
                aria-hidden="true"
                class="assistant-workflow-preview__connections"
                height={{this.layout.height}}
                viewBox="0 0 {{this.layout.width}} {{this.layout.height}}"
                width={{this.layout.width}}
              >
                <defs>
                  <marker
                    id={{this.markerId}}
                    markerHeight="7"
                    markerWidth="7"
                    orient="auto"
                    refX="6"
                    refY="3.5"
                  >
                    <path d="M 0 0 L 7 3.5 L 0 7 z" />
                  </marker>
                </defs>
                {{#each this.layout.connections as |connection|}}
                  <path
                    class="assistant-workflow-preview__connection"
                    d={{connection.path}}
                    marker-end={{this.markerUrl}}
                  />
                  {{#if (connectionLabel connection)}}
                    <text
                      class="assistant-workflow-preview__connection-label"
                      data-connection-type={{connection.connectionType}}
                      data-output-index={{connection.outputIndex}}
                      x={{connection.labelX}}
                      y={{connection.labelY}}
                    >{{connectionLabel connection}}</text>
                  {{/if}}
                {{/each}}
              </svg>

              {{#each this.layout.nodes as |node|}}
                <article
                  class="assistant-workflow-preview__node"
                  data-node-type={{node.type}}
                  style={{this.nodeStyle node}}
                >
                  <span class="assistant-workflow-preview__node-icon">
                    {{dIcon (nodeIcon node.type)}}
                  </span>
                  <span class="assistant-workflow-preview__node-copy">
                    <strong title={{node.name}}>{{node.name}}</strong>
                    <small>{{node.type}}</small>
                    {{#if (this.nodeConnections node)}}
                      <span class="sr-only">
                        {{i18n
                          "discourse_workflows.admin_assistant.preview.connects_to"
                          nodes=(this.nodeConnections node)
                        }}
                      </span>
                    {{/if}}
                  </span>
                </article>
              {{/each}}
            </div>
          </div>
        {{else}}
          <p class="assistant-workflow-preview__fallback">
            {{i18n "discourse_workflows.admin_assistant.preview.unavailable"}}
          </p>
        {{/if}}
        <details class="assistant-workflow-preview__details">
          <summary class="assistant-workflow-preview__footer">
            {{#if this.layout}}
              <span class="assistant-workflow-preview__counts">
                {{i18n
                  "discourse_workflows.admin_assistant.preview.node_count"
                  count=this.preview.nodes.length
                }}
                ·
                {{i18n
                  "discourse_workflows.admin_assistant.preview.connection_count"
                  count=this.preview.connections.length
                }}
                {{#if this.layout.hasCycle}}
                  <span>
                    {{dIcon "arrow-rotate-right"}}
                    {{i18n "discourse_workflows.admin_assistant.preview.cycle"}}
                  </span>
                {{/if}}
              </span>
            {{/if}}
            <span class="assistant-workflow-preview__details-label">
              {{dIcon "caret-right"}}
              {{#if this.preview.shortened}}
                {{i18n
                  "discourse_workflows.admin_assistant.preview.shortened_configuration"
                }}
              {{else}}
                {{i18n
                  "discourse_workflows.admin_assistant.preview.exact_configuration"
                }}
              {{/if}}
            </span>
          </summary>
          <pre><code>{{this.exactConfiguration}}</code></pre>
        </details>
      </section>
    {{/if}}
  </template>
}
import { apiInitializer } from "discourse/lib/api";
import AdminAssistantWorkflowPreview from "../components/admin-assistant/workflow-preview.gjs";
import { extractWorkflowPreview } from "../lib/admin-assistant/workflow-preview.js";

export function decorateWorkflowPreview(element, helper, message) {
  if (
    !helper.renderGlimmer ||
    !message?.blocks?.some((block) => block.type === "confirmation") ||
    !extractWorkflowPreview(element.innerHTML)
  ) {
    return;
  }

  const code = element.querySelector("pre code.lang-admin-assistant-workflow");
  const source = new DOMParser()
    .parseFromString(message.cooked ?? "", "text/html")
    .querySelector("pre code.lang-admin-assistant-workflow");
  if (!code || !source || code.textContent !== source.textContent) {
    return;
  }

  const target = element.ownerDocument.createElement("div");
  code.closest("pre").replaceWith(target);
  helper.renderGlimmer(
    target,
    <template><AdminAssistantWorkflowPreview @message={{message}} /></template>
  );
}

export default apiInitializer((api) => {
  api.decorateChatMessage?.(decorateWorkflowPreview);
});
import Component from "@glimmer/component";
import { tracked } from "@glimmer/tracking";
import { action } from "@ember/object";
import { service } from "@ember/service";
import { ajax } from "discourse/lib/ajax";
import { popupAjaxError } from "discourse/lib/ajax-error";
import { withPluginApi } from "discourse/lib/plugin-api";
import DButton from "discourse/ui-kit/d-button";
import { i18n } from "discourse-i18n";

const ANCHOR_KEYS = {
  read: "read",
  like: "like",
  copy_link: "copyLink",
  flag: "flag",
  edit: "edit",
  bookmark: "bookmark",
  delete: "delete",
  admin: "admin",
  reply: "reply",
};

function dagPosition(workflow, context, postMenuOrder) {
  const position = workflow.position;

  if (position === "first") {
    return { before: context.firstButtonKey };
  }

  if (position === "more_menu") {
    return {
      before: context.lastHiddenButtonKey,
      after: context.secondLastHiddenButtonKey,
    };
  }

  const match = position?.match(/^(before|after)_(.+)$/);
  if (match) {
    const anchor = ANCHOR_KEYS[match[2]];
    if (!anchor) {
      // key from plugin or theme
      return { [match[1]]: match[2] };
    }

    const index = postMenuOrder.indexOf(anchor);
    if (index === -1) {
      // key not in site menu
      return { [match[1]]: anchor };
    }

    if (match[1] === "before") {
      const previous = postMenuOrder[index - 1];
      return previous
        ? { before: anchor, after: previous }
        : { before: anchor };
    }

    return {
      after: anchor,
      before: postMenuOrder[index + 1] || context.buttonKeys.SHOW_MORE,
    };
  }

  return undefined;
}

function buildButtonComponent(workflow) {
  const className = `post-action-menu__workflow-post-button workflow-post-button-${workflow.workflow_id}`;

  class WorkflowPostButton extends Component {
    @service dialog;

    @tracked triggering = false;

    @action
    trigger() {
      if (workflow.confirmation) {
        this.dialog.yesNoConfirm({
          message:
            workflow.confirmation_message ||
            i18n(
              "discourse_workflows.post_button.confirmation_default_message"
            ),
          didConfirm: () => this.triggerWorkflow(),
        });
      } else {
        return this.triggerWorkflow();
      }
    }

    async triggerWorkflow() {
      this.triggering = true;
      try {
        await ajax("/discourse-workflows/trigger-post-button", {
          type: "POST",
          data: {
            workflow_id: workflow.workflow_id,
            trigger_node_id: workflow.trigger_node_id,
            post_id: this.args.post.id,
          },
        });
      } catch (error) {
        popupAjaxError(error);
      } finally {
        this.triggering = false;
      }
    }

    <template>
      <DButton
        class={{className}}
        ...attributes
        @action={{this.trigger}}
        @disabled={{this.triggering}}
